namespace ghidra.features.bsim.query.protocol;




using generic.lsh.vector;
using ghidra.features.bsim.query;
using ghidra.features.bsim.query.description;
using ghidra.util.xml;
using ghidra.xml;
using ghidra.xml;

/**
 * Request that a new executable category be installed for a specific BSim server.
 *
 */
public class InstallCategoryRequest : BSimQuery<ResponseInfo> {

	public string type_name;		// Name of new type of category
	public bool isdatecolumn;	// True if name should be treated as new name for date column
	public ResponseInfo installresponse;
	
	public InstallCategoryRequest() : base("installcategory")
    {
		type_name = "";
		isdatecolumn = false;
	}
	
	/* @Override */
	public void buildResponseTemplate() {
		if (response == null)
			response = installresponse = new ResponseInfo();
	}
	
	/* @Override */
	public void saveXml(Writer fwrite)
    {
		if (!CategoryRecord.enforceTypeCharacters(type_name))
			throw new IOException("Bad characters in requested category type");
		fwrite.append('<').append(name);
		if (isdatecolumn)
			fwrite.append(" datecolumn=\"true\"");
		fwrite.append('>');
		fwrite.append(type_name);
		fwrite.append("</").append(name).append(">\n");
	}

	/* @Override */
	public void restoreXml(XmlPullParser parser, LSHVectorFactory vectorFactory)
    {
		XmlElement el = parser.start(name);
		isdatecolumn = XmlUtilities.parseBoolean(el.getAttribute("datecolumn"));
		type_name = parser.end().getText();
	}

}
